import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int t = in.nextInt();
        int n = in.nextInt();
        int soni = 0;
        for (int i = 0; i < n; i++) {
            int port = in.nextInt();
            int oxirgi = in.nextInt();
            if (t - oxirgi <= 300) soni++;
        }
        System.out.println(soni);
    }
}

